# modules/fabric_capacity/main.tf
variable "environment" {
  type = string
}
variable "sku" {
  type = string
}
variable "admin_members" {
  type = list(string)
}

resource "azurerm_resource_group" "fabric" {
  name     = "rg-fabric-${var.environment}"
  location = "eastus2"
}

resource "fabric_capacity" "this" {
  name                = "fabric-cap-${var.environment}"
  resource_group_name = azurerm_resource_group.fabric.name
  location            = azurerm_resource_group.fabric.location
  sku                 = var.sku
  admin_members       = var.admin_members
  tags = {
    environment = var.environment
    managed_by  = "terraform"
  }
}

output "capacity_id" {
  value = fabric_capacity.this.id
}

# environments/prod/main.tf
module "fabric_capacity" {
  source        = "../../modules/fabric_capacity"
  environment   = "prod"
  sku           = "F128"
  admin_members = ["data-platform-admins@contoso.com"]
}

